import{_ as t,a,o as d,a4 as r}from"./chunks/framework.-FZumj2l.js";const m=JSON.parse('{"title":"Users","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/users/index.md","filePath":"api/graphql-api/admin/settings/users/index.md","lastUpdated":1784902076000}'),s={name:"api/graphql-api/admin/settings/users/index.md"};function o(n,e,i,c,l,h){return d(),a("div",null,e[0]||(e[0]=[r('<h1 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h1><p>The Users menu manages <strong>admin users</strong> — the back-office accounts that sign in to the admin panel. It mirrors the admin <strong>Settings → Users</strong> screen. Each admin user is assigned a single <strong>Role</strong>, and that role is what grants the permissions the user has across the panel and the admin API.</p><h2 id="what-an-admin-user-is" tabindex="-1">What an admin user is <a class="header-anchor" href="#what-an-admin-user-is" aria-label="Permalink to &quot;What an admin user is&quot;">​</a></h2><p>An admin user is a staff login: a <code>name</code>, a unique <code>email</code>, a hashed <code>password</code>, and a <code>roleId</code> pointing at the role that defines what they can do. Admin users are distinct from storefront <strong>Customers</strong> — customers shop the store, admin users run it.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code> / <code>_id</code></td><td>The resource IRI and the numeric user id.</td></tr><tr><td><code>name</code></td><td>Display name of the admin user.</td></tr><tr><td><code>email</code></td><td>Login email — must be unique across admin users.</td></tr><tr><td><code>roleId</code> / <code>roleName</code></td><td>The assigned role&#39;s id and name. The role determines the user&#39;s permissions.</td></tr><tr><td><code>status</code></td><td><code>1</code> = active (can log in), <code>0</code> = inactive.</td></tr><tr><td><code>image</code> / <code>imageUrl</code></td><td>The profile-image storage path and its public URL (both <code>null</code> when no image is set).</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>Timestamps.</td></tr></tbody></table><p>The <code>password</code> and <code>api_token</code> values are <strong>never returned</strong> by any user operation.</p><h2 id="create-update-delete" tabindex="-1">Create, update, delete <a class="header-anchor" href="#create-update-delete" aria-label="Permalink to &quot;Create, update, delete&quot;">​</a></h2><ul><li><strong>Create</strong> — <code>name</code>, <code>email</code>, <code>password</code>, and <code>roleId</code> are required; <code>status</code> defaults to active. The password is stored hashed.</li><li><strong>Update</strong> — partial: send only what changes. <code>password</code> is <strong>optional</strong> — include it to set a new password, omit it to keep the current one. <code>email</code> must stay unique.</li><li><strong>Delete</strong> — removes another admin user. On success the mutation returns a snapshot of the deleted record (<code>id</code>, <code>name</code>, <code>email</code>, <code>roleId</code>, <code>roleName</code>, <code>status</code>).</li></ul><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guard</th><th>Rule</th></tr></thead><tbody><tr><td><strong>No self-delete via the id endpoint</strong></td><td><a href="./delete.html">Delete User</a> refuses to delete the caller&#39;s own account — use <a href="./delete-self.html">Delete My Account</a> instead.</td></tr><tr><td><strong>No last admin</strong></td><td>Neither delete path will remove the final remaining admin, so the store always keeps at least one login.</td></tr></tbody></table><h2 id="delete-my-account-self-delete" tabindex="-1">Delete My Account (self-delete) <a class="header-anchor" href="#delete-my-account-self-delete" aria-label="Permalink to &quot;Delete My Account (self-delete)&quot;">​</a></h2><p>A separate <a href="./delete-self.html">Delete My Account</a> mutation lets an admin remove <strong>their own</strong> account. It requires re-confirming the caller&#39;s current password, refuses the last remaining admin, and — because the account owns the calling token — <strong>invalidates that Bearer token</strong> on success.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List admin users</a></td><td><code>adminSettingsUsers</code> query</td></tr><tr><td><a href="./detail.html">Get an admin user</a></td><td><code>adminSettingsUser(id:)</code> query</td></tr><tr><td><a href="./create.html">Create admin user</a></td><td><code>createAdminSettingsUser</code> mutation</td></tr><tr><td><a href="./update.html">Update admin user</a></td><td><code>updateAdminSettingsUser</code> mutation</td></tr><tr><td><a href="./delete.html">Delete admin user</a></td><td><code>deleteAdminSettingsUser</code> mutation</td></tr><tr><td><a href="./delete-self.html">Delete my account</a></td><td><code>createAdminSettingsUserDeleteSelf</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.users.users.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',17)]))}const p=t(s,[["render",o]]);export{m as __pageData,p as default};
